// read, the load text. The load no longer hides the row: a failed row still
// says so under a ctrl+r.
func (m Model) inventoryStatus() sharedcomponents.Status {
	st := sharedcomponents.Status{Text: sharedcomponents.JobsStatusLine(m.jobs, command.ViewSecurity)}
	if m.inventoryLoading {
		st.Text = "Loading scan inventory..."
	}
	moving := false
	if row, ok := m.inventory.Selected(); ok {
		a := m.rowActivity(row)
		st.Detail = a.Detail
		moving = a.State == indicator.Running || a.State == indicator.Queued
	}
	// The load keeps its own spinner; jobs work gets the activity dot, and only a
	// detail whose dot moves replaces it (a failed row's is fixed).
	st.Spinner = m.inventoryLoading
	st.Activity = !m.inventoryLoading &&
		len(jobs.Unfinished(m.jobs)) > 0 && (!moving || st.Detail.IsZero())
	return st
}

// failedStages names what failed, reading the "<stage>: <reason>" that
// scan.recordStageError writes. The reason stays in the log: a footer is one
// line, and a tool's stderr is not.
func failedStages(errs []string) string {
	stages := make([]string, 0, len(errs))
	for _, e := range errs {
		stage := e
		if idx := strings.Index(e, ": "); idx != -1 {
			stage = e[:idx]
		}
		return m.handleMisconfigFixPrepared(msg)

	case MisconfigFixWrittenMsg:
		return m.handleMisconfigFixWritten(msg)

	case MisconfigVerifiedMsg:
		return m.handleMisconfigVerified(msg)

	case jobs.ChangedMsg:
		return m.handleJobsChanged(msg)

	case jobs.FrameMsg:
		return m.handleFrameMsg(msg)

	case spinner.TickMsg:
		return m.handleSpinnerTick(msg)
	}

	m.footer.Handle(msg)
	return m, nil
}

// handleSpinnerTick advances the spinner while the caches are being read.
//
// It animates a *load* and nothing else now. A scan's frame comes from the
// registry, which holds the one chain for the whole application (D5), and the
// rows are restamped when its snapshot arrives — see handleJobsChanged.
func (m Model) handleSpinnerTick(msg spinner.TickMsg) (tea.Model, tea.Cmd) {
	if !m.spinnerAlive() {
		return m, nil
	}
	var cmd tea.Cmd
	m.spinner, cmd = m.spinner.Update(msg)
	// The footer renders the frame, not a raw one: the spinner already carries
	// theme.SpinnerStyle() and restyling it would nest one sequence in another
	// (Rule 128).
	m.footer.SetSpinnerFrame(m.spinner.View())
	return m, cmd
}

// handlePaste hands pasted text to the filter bar of the table on screen while
// it has the keyboard and no modal is open; otherwise a paste is dropped, never
// read as keys (Rule 111).
func (m Model) handlePaste(msg tea.PasteMsg) (tea.Model, tea.Cmd) {
	if m.confirmModal != nil || m.scanAllModal != nil {
		return m, nil

	state  ViewState
	result *scan.Result

	// deps is the router's detection of the scanners, nil until it lands.
	deps *scan.Report

	// Inventory state
	inventory datatable.Model[scanTarget]
	// spinner animates the view's own loads (caches, remediation) in the footer.
	spinner spinner.Model

	// jobs is the router snapshot of everything running anywhere. See jobs.go:
	// the rows' activity is derived from it, so there is no in-flight state here
	// to carry across a reload.
	jobs []jobs.Run

	// failures is a copy of the registry's remembered failures, replaced (never
	// merged) by handleJobsChanged, and contextName the context the snapshot was
	// built for (ChangedMsg.Context).
	failures    []jobs.Failure
	contextName string

	// inventoryLoading is true while loadInventoryCmd is in flight. It exists
	// because an empty table and a table that has not answered yet look the
	// same, and they mean opposite things: "Nothing scanned yet" asserted
	// before the caches were read is a claim the view cannot make, and the one
	// the user saw flash by before the list appeared.
	//
	// It also keeps the spinner chain alive, which is why it is read by
	// spinnerAlive rather than only by the renderer.
	inventoryLoading bool

	// targetPath is what the result on screen is about — an image reference or a
	// repository path. It is the directory .gitleaksignore is written into, so
	// it is the key and never a display form.
}

// New creates a new security scanner view, on the inventory.
// New builds the view. The secret store comes in at construction, like
// workspaces': the CI stage needs the context's forge token, and a rescan
// started here must produce the same grade as the same rescan started from ws —
// two screens grading one repository differently is the shape §3.11 and §3.12
// each had to undo.
func New(cfg *config.Config, secrets credentials.Storage) Model {
	s := spinner.New()
	s.Spinner = spinner.Dot
	s.Style = theme.SpinnerStyle()

	t := datatable.New(datatable.Config[scan.Finding]{
		Columns:        findingColumns(),
		SortColumn:     -1, // the order the scanner reported
		SelectedStyles: findingSelectedStyles,
		Tokens:         severityTokens(),
		TokenMatch:     matchesSeverity,
	})

	return Model{
		config:    cfg,
		secrets:   secrets,
		state:     StateInventory,
		inventory: newInventoryTable(cfg.Scan.Categories.CI.Enabled, cfg.Scan.Categories.Misconfig.Enabled),
		// True from construction, because Init loads unconditionally: a view
		// that starts saying "not loading" would render the empty message for
		// the frame before the first Cmd runs.
		inventoryLoading: true,
		spinner:          s,
		findingsTable:    t,
		remediation:      newRemediationState(),
	}
}

// filters the user is looking through. It is what a verification re-scan hands
// back, so the table stops listing a rule the edit has already dealt with.
func (m *Model) setResult(result *scan.Result) {
	m.result = result
	m.targetPath = result.Target
	m.targetLabel = labelForResult(m.config, result)
	m.updateFindingsTable()
}

// Init initializes the model
func (m Model) Init() tea.Cmd {
	return tea.Batch(
		m.spinner.Tick,
		// Loaded whatever the opening state: a view opened on a result returns
		// to the inventory on ctrl+r, and reading two small files is cheaper
		// than the branch that would decide not to.
		loadInventoryCmd(m.ciForgeURL()),
	)
}

// InEditMode reports whether a field or a modal has the keyboard, which is what
	}
	job := inventoryScanJob{Kind: target.Kind, Name: target.Name}
	opts := m.scanOptions()
	return m, jobs.StartInContext(
		m.scanRun([]string{target.Name}),
		func(contextName string) tea.Cmd {
			return rescanCmd([]inventoryScanJob{job}, opts, contextName)
		},
	)
}

// spinnerTickIfIdle restarts the spinner chain, unless something is already
// keeping it alive. handleSpinnerTick stops scheduling once nothing is running,
// so a rescan has to start it again — and starting a second chain alongside a
// live one makes the frames advance at twice the rate.
func (m Model) spinnerTickIfIdle() tea.Cmd {
	if m.spinnerAlive() {
		return nil
	}
	return m.spinner.Tick
}

// spinnerAlive decides whether this view's own frames keep coming.
//
// One condition answers it now: a load. A rescan used to be the other, and
// keeping it here would be a second chain beside the router's — which is the
// failure D5 removed, not one to reintroduce a view at a time.
func (m Model) spinnerAlive() bool {
	return m.inventoryLoading || m.remediationBusy()
}

// reloadInventory re-reads the caches and says so in the footer.
//
// The tick is taken **before** the flag flips: spinnerTickIfIdle reads
// spinnerAlive, so setting the flag first would make it answer "already
// running" about the chain this reload is trying to start.
func (m Model) reloadInventory() (tea.Model, tea.Cmd) {
	tick := m.spinnerTickIfIdle()
	m.inventoryLoading = true
	return m, tea.Batch(tick, loadInventoryCmd(m.ciForgeURL()))
}

// confirmRescanAll asks before rescanning everything, and the purge is the
// modal's checkbox rather than a second key.
//
// A and ctrl+a differed only by a modifier, and nothing in their shape said
// which one purged — the closest this application came to losing data by
// accident (§3.26). The destructive half is now a deliberate gesture, under the
// eyes of whoever triggers it.
func (m Model) confirmRescanAll() (tea.Model, tea.Cmd) {
	if all := m.canRescanAll(); !all.Enabled() {
		return m, m.footer.Warn(all.Reason)
	}
	m.scanAllModal = sharedcomponents.NewOptionConfirmModal(
		"Scan All",
		fmt.Sprintf("Rescan all %d targets?", len(m.inventory.Items())),
func (m *Model) enterRemediation() tea.Cmd {
	if m.result == nil || m.remediation.phase != phaseIdle {
		return nil
	}
	m.remediation.target = m.result.Target
	if m.result.TargetType != scan.TargetDirectory {
		m.remediation.phase = phaseReady
		return nil
	}
	// The tick is taken before the phase flips, or spinnerTickIfIdle would
