// read, the load text. The load no longer hides the row: a failed row still
// says so under a ctrl+r.
func (m Model) inventoryStatus() sharedcomponents.Status {
	st := sharedcomponents.Status{Text: sharedcomponents.JobsStatusLine(m.jobs, command.ViewSecurity)}
	if m.inventoryLoading {
		st.Text = "Loading scan inventory..."
	}
	moving := false
	if row, ok := m.inventory.Selected(); ok {
		a := m.rowActivity(row)
		st.Detail = a.Detail
		moving = a.State == indicator.Running || a.State == indicator.Queued
	}
	// The load keeps its own spinner; jobs work gets the activity dot, and only a
	// detail whose dot moves replaces it (a failed row's is fixed).
	st.Spinner = m.inventoryLoading
	st.Activity = !m.inventoryLoading &&
		len(jobs.Unfinished(m.jobs)) > 0 && (!moving || st.Detail.IsZero())
	return st
}

// failedStages names what failed, reading the "<stage>: <reason>" that
// scan.recordStageError writes. The reason stays in the log: a footer is one
// line, and a tool's stderr is not.
func failedStages(errs []string) string {
	stages := make([]string, 0, len(errs))
	for _, e := range errs {
		stage := e
		if idx := strings.Index(e, ": "); idx != -1 {
			stage = e[:idx]
		}
		return m.handleMisconfigFixPrepared(msg)

	case MisconfigFixWrittenMsg:
		return m.handleMisconfigFixWritten(msg)

	case MisconfigVerifiedMsg:
		return m.handleMisconfigVerified(msg)

	case jobs.ChangedMsg:
		return m.handleJobsChanged(msg)

	case jobs.FrameMsg:
		return m.handleFrameMsg(msg)

	case spinner.TickMsg:
		return m.handleSpinnerTick(msg)
	}

	m.footer.Handle(msg)
	return m, nil
}

// handleSpinnerTick advances the spinner while the caches are being read.
//
// It animates a *load* and nothing else now. A scan's frame comes from the
// registry, which holds the one chain for the whole application (D5), and the
// rows are restamped when its snapshot arrives — see handleJobsChanged.
func (m Model) handleSpinnerTick(msg spinner.TickMsg) (tea.Model, tea.Cmd) {
	if !m.spinnerAlive() {
		return m, nil
	}
	var cmd tea.Cmd
	m.spinner, cmd = m.spinner.Update(msg)
	// The footer renders the frame, not a raw one: the spinner already carries
	// theme.SpinnerStyle() and restyling it would nest one sequence in another
	// (Rule 128).
	m.footer.SetSpinnerFrame(m.spinner.View())
	return m, cmd
}

// handlePaste hands pasted text to the filter bar of the table on screen while
// it has the keyboard and no modal is open; otherwise a paste is dropped, never
// read as keys (Rule 111).
func (m Model) handlePaste(msg tea.PasteMsg) (tea.Model, tea.Cmd) {
	if m.confirmModal != nil || m.scanAllModal != nil {
		return m, nil

	state  ViewState
	result *scan.Result

	// deps is the router's detection of the scanners, nil until it lands.
	deps *scan.Report

	// Inventory state
	inventory datatable.Model[scanTarget]
	// spinner animates the view's own loads (caches, remediation) in the footer.
	spinner spinner.Model

	// jobs is the router snapshot of everything running anywhere. See jobs.go:
	// the rows' activity is derived from it, so there is no in-flight state here
	// to carry across a reload.
	jobs []jobs.Run

	// failures is a copy of the registry's remembered failures, replaced (never
	// merged) by handleJobsChanged, and contextName the context the snapshot was
	// built for (ChangedMsg.Context).
	failures    []jobs.Failure
	contextName string

	// inventoryLoading is true while loadInventoryCmd is in flight. It exists
	// because an empty table and a table that has not answered yet look the
	// same, and they mean opposite things: "Nothing scanned yet" asserted
	// before the caches were read is a claim the view cannot make, and the one
	// the user saw flash by before the list appeared.
	//
	// It also keeps the spinner chain alive, which is why it is read by
	// spinnerAlive rather than only by the renderer.
	inventoryLoading bool

	// targetPath is what the result on screen is about — an image reference or a
	// repository path. It is the directory .gitleaksignore is written into, so
	// it is the key and never a display form.
}

